use semio_framework_test_fixtures::fixture_text;
use super::super::{PersistentList,PERSISTENT_PAGE_FANOUT,RetirementDemand,RetainedCloneGrant,SealedShared,SharedIssuer};
use crate::{retirement::RetireOwned,retained_clone::RetainedCloneSource};
use std::fmt::Write;
fn observe<T>(operation:impl FnOnce()->T)->(T,(usize,usize)){crate::value::observe_retirement_allocations(operation)}
#[derive(crate::RetireOwned,PartialEq,Eq)]#[value(crate="crate")]struct Row(i64);
impl std::fmt::Debug for Row{fn fmt(&self,f:&mut std::fmt::Formatter<'_>)->std::fmt::Result{self.0.fmt(f)}}
struct Sink{bytes:[u8;1024],len:usize}
impl Write for Sink{fn write_str(&mut self,value:&str)->std::fmt::Result{let end=self.len.checked_add(value.len()).ok_or(std::fmt::Error)?;let target=self.bytes.get_mut(self.len..end).ok_or(std::fmt::Error)?;target.copy_from_slice(value.as_bytes());self.len=end;Ok(())}}
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn generous()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:65536,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:4096}}
fn make(rows:&[i64])->PersistentList<Row>{let mut pages=Vec::new();for chunk in rows.chunks(PERSISTENT_PAGE_FANOUT){let issued=std::array::from_fn(|i|chunk.get(i).map(|value|SealedShared::admit(Row(*value),SharedIssuer::owned(),generous()).unwrap_or_else(|_|panic!("row issuance")).0));pages.push(PersistentList::admit_leaf(issued,chunk.len(),grant(PersistentList::<Row>::page_birth_demand())).unwrap_or_else(|_|panic!("leaf issuance")).0);}while pages.len()>1{let mut nodes=pages.into_iter();let mut parents=Vec::new();loop{let children=std::array::from_fn(|_|nodes.next());if children[0].is_none(){break;}parents.push(PersistentList::admit_branch(children,grant(PersistentList::<Row>::page_birth_demand())).unwrap_or_else(|_|panic!("branch issuance")).0);}pages=parents;}pages.pop().unwrap_or_default()}
fn original<T:RetireOwned+Send+Sync+'static>(value:T)->RetainedCloneSource<T>{RetainedCloneSource::admit_owned(value,(),generous()).unwrap_or_else(|_|panic!("original source")).0}
#[derive(Clone,Copy)]struct ClosurePolicy{body_bytes:usize,maximum_turns:usize,maximum_idle_turns:usize}
fn planned_body(body:usize,quoted_copy:usize)->usize{body.max(quoted_copy)}
fn close<T:RetireOwned+Send+Sync+'static>(s:&mut RetainedCloneSource<T>,policy:ClosurePolicy){let mut idle=0;for turn in 0..policy.maximum_turns{if s.terminal_is_empty(){return;}let mut d=s.next_close_demand(policy.body_bytes).unwrap();let body=planned_body(policy.body_bytes,d.copy_bytes);if body!=policy.body_bytes{d=s.next_close_demand(body).unwrap();}assert!(d.copy_bytes<=body,"quoted closure copy exceeds selected body");let admitted=RetainedCloneGrant{maximum_copy_bytes:body,..grant(d)};let progress=s.close_step(admitted).unwrap().progress();assert!(progress.fits(admitted),"closure receipt exceeds selected grant");if progress==Default::default(){idle+=1;}else{idle=0;}assert!(idle<policy.maximum_idle_turns||s.terminal_is_empty(),"original source closure stalled at turn {turn}: body={body} demand={d:?}");}assert!(s.terminal_is_empty(),"original source closure exceeded finite turns");}
#[test]fn borrowed_immutable_observations_preserve_original_rows_without_clone_or_heap(){
 let law:serde_json::Value=serde_json::from_str(fixture_text!("../../⚖️observation/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();
 let number=|key:&str|usize::try_from(law["closure"][key].as_u64().unwrap()).unwrap();let policy=ClosurePolicy{body_bytes:number("bodyBytes"),maximum_turns:number("maximumTurns"),maximum_idle_turns:number("maximumIdleTurns")};
 for c in law["closureBudgets"].as_array().unwrap(){let n=|key:&str|usize::try_from(c[key].as_u64().unwrap()).unwrap();assert_eq!(planned_body(n("bodyBytes"),n("quotedCopyBytes")),n("expectedCopyBytes"));}
 let slot_bytes=size_of::<Box<dyn crate::retirement::RetirementCursor>>();let frontier_law=law["frontierPayloads"].as_array().unwrap().iter().find(|row|row["elementBytes"].as_u64().unwrap()as usize==slot_bytes).unwrap();let expected_payload=frontier_law["expectedCapacityBytes"].as_u64().unwrap()as usize;assert_eq!(frontier_law["expectedSlots"].as_u64().unwrap()as usize*slot_bytes,expected_payload);
 let mut frame=crate::retirement::controlled::ControlledRetirement::new(Row(1)).unwrap_or_else(|_|panic!("original row frontier"));let mut payload_seen=false;for turn in 0..policy.maximum_turns{if frame.terminal_is_empty(){break;}let d=frame.next_demand(policy.body_bytes).unwrap();if turn==1{assert_eq!(d.capacity_bytes,expected_payload,"selected frontier quote must fund the actual payload page");payload_seen=true;}let admitted=RetainedCloneGrant{maximum_copy_bytes:policy.body_bytes,..grant(d)};if d.capacity_bytes>0{let(step,heap)=observe(||frame.step(RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..admitted}).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(frame.next_demand(policy.body_bytes).unwrap(),d);}let(step,heap)=observe(||frame.step(admitted).unwrap());let progress=step.progress();assert!(progress.fits(admitted));assert_eq!(heap,(progress.retained_capacity_bytes,progress.released_bytes));assert!(progress!=Default::default()||frame.terminal_is_empty(),"selected frontier event stalled at turn {turn}: {d:?}");}assert!(payload_seen&&frame.terminal_is_empty());assert_eq!(observe(||drop(frame)).1,(0,0));
 for c in law["cases"].as_array().unwrap(){let values=|key:&str|c[key].as_array().unwrap().iter().map(|v|v.as_i64().unwrap()).collect::<Vec<_>>();let mut a=original(make(&values("left")));let mut b=original(make(&values("right")));let pointers:Vec<_>=a.borrow().get().iter().map(std::ptr::from_ref).collect();let mut sink=Sink{bytes:[0;1024],len:0};
  let((equal,()),heap)=observe(||{let equal=a.borrow().get()==b.borrow().get();write!(&mut sink,"{:?}",a.borrow().get()).unwrap();(equal,())});assert_eq!(heap,(0,0));assert_eq!(equal,c["equal"].as_bool().unwrap());assert_eq!(std::str::from_utf8(&sink.bytes[..sink.len]).unwrap(),c["debug"].as_str().unwrap());for(i,row)in a.borrow().get().iter().enumerate(){assert_eq!(std::ptr::from_ref(row),pointers[i]);}
  let mut x=original(SealedShared::admit(Row(7),SharedIssuer::owned(),generous()).unwrap_or_else(|_|panic!("sealed row")).0);let mut y=original(SealedShared::admit(Row(7),SharedIssuer::owned(),generous()).unwrap_or_else(|_|panic!("sealed row")).0);let p=std::ptr::from_ref(x.borrow().get().get());let mut scalar=Sink{bytes:[0;1024],len:0};let(_,heap)=observe(||{assert_eq!(x.borrow().get(),y.borrow().get());write!(&mut scalar,"{:?}",x.borrow().get()).unwrap();});assert_eq!(heap,(0,0));assert_eq!(&scalar.bytes[..scalar.len],b"7");assert_eq!(std::ptr::from_ref(x.borrow().get().get()),p);close(&mut x,policy);close(&mut y,policy);close(&mut a,policy);close(&mut b,policy);assert_eq!(observe(||drop((x,y,a,b))).1,(0,0));
 }
}
